{
  "雪容": {
    "信任度": [
      60,
      "雪容对{{user}}的信任程度，范围从0到100。日常交流或特定事件会使其在-5到+5之间浮动，积极互动增加，消极互动减少。提出不适当要求会使其在-5~-20浮动，是否不适当主要却决于信任度。"
    ],
    "财富": [
      2000,
      "雪容拥有的货币数量。通过完成艺师工作或出售物品累积，花费时减少。"
    ],
   "性行为次数": [
      0,
      "雪容进行侵入式性行为时增加，不得减少"
    ],
  },
  "{{user}}": {
    "财富": [
      1000,
      "{{user}}拥有的货币数量。通过经营月华阁、完成任务或出售物品累积，花费时减少。"
    ]
  },
  "当前阶段": [
    1,
    "故事当前所处的宏观发展阶段。通常在完成某个大型剧情节点后由系统或特定指令推进。初始为1，未明确要求变动时保持不变。"
  ],
  "月华阁": {
    "声望": [
      0,
      "月华阁在江湖中的名声和影响力，范围从-100（声名狼藉）到100（声名远播）。顾客评价或女工反馈会使其在-5到5之间浮动，正面反馈增加，负面反馈减少。"
    ],
    "合法度": [
      20,
      "月华阁的经营符合《大唐青楼管理律例》的程度，范围从-100（完全非法）到100（完全合法）。各种经营行为会使其在-5到5之间浮动，符合律例的行为增加，违规行为减少。"
    ],
    "地图": [
      [
        "一楼大厅",
        "101雅间",
        "102雅间",
        "二楼",
        "女工休息室",
        "女工更衣室",
        "201雅间",
        "202雅间"
      ],
      "月华阁内部可探索的地点列表。阁主（{{user}}）进行建设或扩建时，此列表会更新，添加新的地点。"
    ],
    "女工数量": {
      "侍女": [
        3,
        "月华阁现有的侍女数量。通过招募可增加，离开或解雇时减少。"
      ],
      "艺师": [
        1,
        "月华阁现有的艺师（如歌姬、舞姬）数量。通过招募可增加，离开或解雇时减少。"
      ],
      "医女": [
        1,
        "月华阁现有的医女数量。通过招募可增加，离开或解雇时减少。"
      ],
      "女执事": [
        1,
        "月华阁现有的女执事数量。通过招募可增加，离开或解雇时减少。"
      ]
    },
    "顾客数量": [
      10,
      "月华阁每日或当前时段的顾客数量。受月华阁声望、合法度及随机事件影响而波动。"
    ]
  },
  "世界": {
    "开业天数": [
      1,
      "月华阁自开业以来已经过去的天数。通常在每次故事日结束或特定时间点递增1。"
    ]
  }
}
